apply.studio_css:
/* Typography Studio · personality=trust · pair=lora_manrope_calm · ssot */
:root {
  --font-display: "Lora", Georgia, serif;
  --font-body: "Manrope", "Segoe UI", system-ui, sans-serif;
  --font-sans: "Manrope", "Segoe UI", system-ui, sans-serif;
  --type-body-lh: 1.8;
  --type-headline-lh: 1.18;
  --type-track-display: 0.01em;
  --type-track-body: 0.02em;
  --type-btn-weight: 500;
}
body {
  font-family: var(--font-body);
  font-weight: 400;
  line-height: var(--type-body-lh);
  letter-spacing: var(--type-track-body);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-wrap: anywhere;
  word-break: normal;
}
body .hero h1,
body .hero .hero-title,
body h1,
body .page-title,
body .section h2,
body h2,
body h3 {
  font-family: var(--font-display);
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
  hyphens: auto;
  white-space: normal;
}
body .hero h1,
body .hero .hero-title,
body h1,
body .page-title {
  font-weight: 500;
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: var(--type-headline-lh);
  letter-spacing: var(--type-track-display);
}
body .section h2,
body h2 {
  font-weight: 500;
  font-size: clamp(1.35rem, 2.1vw, 1.85rem);
  line-height: 1.22;
  letter-spacing: var(--type-track-display);
}
body .btn,
body button.btn,
body a.btn {
  font-family: var(--font-body);
  font-weight: var(--type-btn-weight);
  letter-spacing: 0.02em;
  white-space: normal;
  max-width: 100%;
}
@media (max-width: 720px) {
  body { line-height: 1.65; }
  body .hero h1,
  body .hero .hero-title,
  body h1 {
    font-size: clamp(1.65rem, 5.8vw, 2.15rem);
    letter-spacing: -0.015em;
    max-width: 100%;
  }
}

